#include "inference/solver_model.hpp"
#include "ode/advanced_ode_native.hpp"
#include "runtime/data_io.hpp"
#include <chrono>
#include <cmath>
#include <iostream>
#include <numeric>

using namespace penta;
namespace {
int checks=0;
void check(bool yes,const char* message){++checks;if(!yes)throw std::runtime_error(message);}
bool close(double a,double b,double tolerance=1e-7){return std::abs(a-b)<=tolerance*(1+std::abs(b));}
template<class F>void rejects(F action,const char* message){try{action();}catch(const std::exception&){check(true,message);return;}throw std::runtime_error(message);}
struct Problem {
    std::vector<double> initial{.3},starts{.2,.5,1.1,1.6},indices{0,1,2,3},y,grid{.6,.7,.8};penta_inference_request_v1 request{};
    Problem(inference::SolverModelBridge& model){for(const double t:model.model().times)y.push_back(2*std::exp(-.7*t));auto& r=request;r.struct_size=sizeof(r);r.operation=PENTA_INF_MULTISTART;r.dimension=1;r.observations=r.prediction_count=4;r.runs=4;r.seed=729;r.batch_size=2;r.initial=initial.data();r.starts=starts.data();r.x=indices.data();r.y=y.data();r.prediction_x=indices.data();r.confidence=.95;r.max_wall_seconds=60;r.block_length=1;r.model_context=&model;r.model=inference::SolverModelBridge::evaluate;auto& f=r.fit;f.struct_size=sizeof(f);f.method=1;f.loss_scale=1;f.dimension=1;f.residual_count=4;f.max_iterations=100;f.max_evaluations=1000;f.maximum_wall_seconds=30;f.function_tolerance=f.gradient_tolerance=f.parameter_tolerance=1e-10;f.noise_variance=-1;}
};
}
int main(int argc,char** argv){
    const auto directory=std::filesystem::temp_directory_path()/("penta-solver-refits-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));
    try{
        const auto modules=argc>1?std::filesystem::absolute(argv[1]):std::filesystem::path{};native_functions::Options native;native.build.cacheDirectory=directory/"kernels";
        const auto source=language::analyse("ode decay(t,real x;real rate){x'=-rate*x;}");check(source.ok(),"Native ODE refit fixture parses");const auto& definition=*source.program.statements[0].ode;
        inference::SolverModel model;model.model.kind=sensitivity::solver::Kind::Ode;model.model.initial={2};model.model.parameters={.3};model.model.ode=std::make_shared<ode::PreparedModel>(definition,native.build);model.model.callback=std::make_shared<native_functions::Callback>(ode::rhsFunction(definition),native);model.model.native=native.build;model.model.stateCoordinates=1;model.model.odeOptions.t1=1;model.model.odeOptions.sampleStep=.1;model.model.odeOptions.rtol=1e-10;model.model.odeOptions.atol=1e-12;model.model.odeOptions.method=ode::Method::Bdf;model.times={0,.25,.5,1};model.observationCoordinates={0};model.selectors={0};model.validate();
        const auto predicted=model.evaluate(std::array<double,1>{.7},true);for(std::size_t k=0;k<4;++k){check(close(predicted.values[k],2*std::exp(-.7*model.times[k]),2e-8),"Native ODE trajectory matches the analytic exponential");check(close(predicted.jacobian[k],-model.times[k]*predicted.values[k],2e-7),"Compiler/CVODES parameter sensitivities match the analytic model Jacobian");}
        inference::SolverModelBridge bridge(model);double value=0,jacobian=0;char error[2048]{};const double rate=.7;for(unsigned k=0;k<4;++k)check(inference::SolverModelBridge::evaluate(&bridge,&rate,1,k,&value,&jacobian,error,sizeof(error))==0,"Sample-index ODE lookup succeeds");check(bridge.solves()==1,"All observation rows reuse one complete native trajectory/Jacobian at a physical point");
        inference::Module module(modules);Problem problem(bridge);inference::Options options;options.threads=4;options.modelIdentity=model.fingerprint();options.checkpoint=directory/"ode-refits.json";const auto parallel=module.run(problem.request,options);check(parallel.report.successful==4,"Independent native ODE fits converge from all supplied starts");for(const auto fitted:parallel.parameters)check(close(fitted,.7,1e-6),"Parallel ODE multistart recovers the independent reference rate");check(parallel.parallel.threadsUsed>=1&&parallel.parallel.threadsUsed<=4,"Parallel ODE refits respect the shared thread budget");const auto solves=bridge.solves();options.resume=true;options.threads=1;const auto resumed=module.run(problem.request,options);check(resumed.restored==4&&bridge.solves()==solves,"Completed ODE-refit checkpoints resume without reintegration");check(resumed.parameters==parallel.parameters,"Resumed ODE fits retain exact completed physical parameters");
        const auto bytes=runtime::dataio::readBytes(options.checkpoint);options.modelIdentity="different-solver-grid";rejects([&]{(void)module.run(problem.request,options);},"Changed solver observation identity rejects refit checkpoint reuse");check(runtime::dataio::readBytes(options.checkpoint)==bytes,"Incompatible solver-refit resume preserves previous checkpoint bytes");options.checkpoint.clear();options.resume=false;options.modelIdentity=model.fingerprint();
        problem.request.operation=PENTA_INF_PROFILE;problem.request.runs=problem.grid.size();problem.request.profile_grid=problem.grid.data();problem.request.profile_coordinate=0;const auto profile=module.run(problem.request,options);for(std::size_t row=0;row<problem.grid.size();++row){double expected=0;for(std::size_t k=0;k<4;++k)expected+=.5*std::pow(2*std::exp(-problem.grid[row]*model.times[k])-problem.y[k],2);check(close(profile.costs[row],expected,2e-7),"No-nuisance ODE profile matches direct analytic SSE");}
        auto finiteModel=model;finiteModel.jacobian="finite_difference";const auto numeric=finiteModel.evaluate(std::array<double,1>{.7},true);for(std::size_t k=0;k<4;++k)check(close(numeric.jacobian[k],predicted.jacobian[k],3e-5),"Finite differences of native ODE solves agree with compiler/CVODES sensitivities");
        const auto reaction=language::analyse("native function real reaction(real u,real t,real x,real rate){return -rate*u;}");check(reaction.ok(),"Native PDE reaction fixture parses");inference::SolverModel pde;pde.model.kind=sensitivity::solver::Kind::Pde1;pde.model.initial=std::vector<double>(5,2);pde.model.parameters={.3,.1};pde.model.reactionParameters=1;pde.model.stateCoordinates=1;pde.model.callback=std::make_shared<native_functions::Callback>(*reaction.program.statements[0].function,native);pde.model.native=native.build;pde.model.moduleDirectory=modules;pde.model.x={0,.25,.5,.75,1};pde.model.left=pde.model.right={0};auto& q=pde.model.pde.base;q.struct_size=sizeof(pde.model.pde);q.nodes=5;q.components=1;q.boundary=2;q.length=1;q.diffusion=.1;q.t1=.2;q.time_step=.005;q.sample_step=.05;q.max_steps=10000;q.max_reaction_evaluations=100000;q.max_wall_seconds=30;pde.times={0,.05,.1,.2};pde.observationCoordinates={2};pde.selectors={0};pde.jacobian="finite_difference";pde.validate();const auto field=pde.evaluate(std::array<double,1>{.7},true);for(std::size_t k=0;k<4;++k){check(close(field.values[k],2*std::exp(-.7*pde.times[k]),2e-8),"Native FD PDE uniform-field trajectory matches the independent exponential");check(close(field.jacobian[k],-pde.times[k]*field.values[k],2e-5),"PDE refit parameter derivatives are explicit finite differences of complete native solves");}
        inference::SolverModelBridge pdeBridge(pde);Problem pdeProblem(pdeBridge);options.threads=4;options.modelIdentity=pde.fingerprint();const auto pdeFits=module.run(pdeProblem.request,options);check(pdeFits.report.successful==4,"Independent native PDE refits converge through the shared Ceres scheduler");for(const auto fitted:pdeFits.parameters)check(close(fitted,.7,3e-5),"Parallel PDE refits recover the independent decay parameter");
    }catch(const std::exception& exception){std::cerr<<"FAIL after "<<checks<<" checks: "<<exception.what()<<'\n';return 1;}
    std::error_code ignored;std::filesystem::remove_all(directory,ignored);std::cout<<checks<<" native ODE/PDE parallel-refit checks passed.\n";
}
